// Keeps the events of this recipe, then builds the request(s) for Send the invitation.
const WANTED = []
const out = []
for (const item of $input.all()) {
  const msg = item.json.body ?? item.json
  if (WANTED.length && !WANTED.includes(msg.event)) continue
  // Calendly "invitee.created": e-mail the invitee the guest link of your live (create it once in LearnFloo:
  // the live → Invite → link named "Calendly"), tagged with utm_source=calendly.
  const LIVE_LINK = 'https://app.learnfloo.com/invite/XXXX'
  const MAILER = 'https://api.resend.com/emails' // any e-mail API; Resend shown here
  const p = msg.payload ?? {}
  if (msg.event !== 'invitee.created' || !p.email) continue
  const link = `${LIVE_LINK}?utm_source=calendly&utm_medium=booking`
  out.push({ json: { method: 'POST', url: MAILER, body: { from: 'you@yourdomain.com', to: p.email, subject: 'Join my next live', text: `Hi ${p.first_name ?? p.name ?? ''},\n\nThanks for booking a call. Before we talk, join my next live: ${link}\n` } } })
}
return out
